#include "pal_wifi.h"

#include <string.h>
#include "freertos/FreeRTOS.h"
#include "freertos/event_groups.h"
#include "esp_wifi.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_log.h"

static const char *TAG = "pal_wifi";

#define WIFI_CONNECTED_BIT  BIT0
#define WIFI_FAIL_BIT       BIT1

static EventGroupHandle_t s_event_group = NULL;
static esp_netif_t *s_sta_netif = NULL;
static pal_wifi_status_t s_status = PAL_WIFI_DISCONNECTED;
static pal_wifi_callback_t s_callback = NULL;
static void *s_callback_data = NULL;
static int s_retry_count = 0;
static int s_max_retries = 10;

static void notify(pal_wifi_event_t ev) {
    if (s_callback) s_callback(ev, s_callback_data);
}

static void wifi_event_handler(void *arg, esp_event_base_t base,
                               int32_t id, void *event_data) {
    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
        esp_wifi_connect();
    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
        s_status = PAL_WIFI_DISCONNECTED;
        notify(PAL_WIFI_EVENT_DISCONNECTED);
        if (s_retry_count < s_max_retries) {
            s_retry_count++;
            s_status = PAL_WIFI_CONNECTING;
            esp_wifi_connect();
            ESP_LOGI(TAG, "Retry %d/%d", s_retry_count, s_max_retries);
        } else {
            s_status = PAL_WIFI_FAILED;
            xEventGroupSetBits(s_event_group, WIFI_FAIL_BIT);
        }
    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
        s_retry_count = 0;
        s_status = PAL_WIFI_CONNECTED;
        xEventGroupSetBits(s_event_group, WIFI_CONNECTED_BIT);
        notify(PAL_WIFI_EVENT_GOT_IP);
    } else if (base == IP_EVENT && id == IP_EVENT_STA_LOST_IP) {
        notify(PAL_WIFI_EVENT_LOST_IP);
    }
}

int pal_wifi_init(void) {
    if (s_event_group) return 0;

    s_event_group = xEventGroupCreate();

    esp_err_t err = esp_netif_init();
    if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) return -1;

    err = esp_event_loop_create_default();
    if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) return -1;

    s_sta_netif = esp_netif_create_default_wifi_sta();

    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
    if (esp_wifi_init(&cfg) != ESP_OK) return -2;

    esp_event_handler_instance_t inst_any, inst_ip;
    esp_event_handler_instance_register(WIFI_EVENT, ESP_EVENT_ANY_ID,
                                        &wifi_event_handler, NULL, &inst_any);
    esp_event_handler_instance_register(IP_EVENT, IP_EVENT_STA_GOT_IP,
                                        &wifi_event_handler, NULL, &inst_ip);
    esp_event_handler_instance_register(IP_EVENT, IP_EVENT_STA_LOST_IP,
                                        &wifi_event_handler, NULL, NULL);

    if (esp_wifi_set_mode(WIFI_MODE_STA) != ESP_OK) return -3;

    ESP_LOGI(TAG, "WiFi STA initialized");
    return 0;
}

int pal_wifi_connect(const pal_wifi_config_t *config) {
    if (!config || !config->ssid) return -1;

    s_max_retries = config->max_retries ? config->max_retries : 10;
    s_retry_count = 0;
    s_status = PAL_WIFI_CONNECTING;

    wifi_config_t wifi_cfg = {0};
    strncpy((char *)wifi_cfg.sta.ssid, config->ssid, sizeof(wifi_cfg.sta.ssid) - 1);
    if (config->password) {
        strncpy((char *)wifi_cfg.sta.password, config->password, sizeof(wifi_cfg.sta.password) - 1);
    }
    wifi_cfg.sta.threshold.authmode = config->password && strlen(config->password) > 0
                                     ? WIFI_AUTH_WPA2_PSK : WIFI_AUTH_OPEN;

    esp_wifi_set_config(WIFI_IF_STA, &wifi_cfg);
    esp_wifi_start();

    uint32_t timeout = config->timeout_ms ? config->timeout_ms : 30000;
    EventBits_t bits = xEventGroupWaitBits(s_event_group,
                                           WIFI_CONNECTED_BIT | WIFI_FAIL_BIT,
                                           pdFALSE, pdFALSE,
                                           pdMS_TO_TICKS(timeout));

    if (bits & WIFI_CONNECTED_BIT) {
        ESP_LOGI(TAG, "Connected to %s", config->ssid);
        return 0;
    }
    ESP_LOGW(TAG, "Connection failed");
    return -1;
}

int pal_wifi_disconnect(void) {
    s_status = PAL_WIFI_DISCONNECTED;
    return esp_wifi_disconnect() == ESP_OK ? 0 : -1;
}

int pal_wifi_set_hostname(const char *hostname) {
    if (!hostname || !s_sta_netif) return -1;
    return esp_netif_set_hostname(s_sta_netif, hostname) == ESP_OK ? 0 : -1;
}

bool pal_wifi_is_connected(void) {
    return s_status == PAL_WIFI_CONNECTED;
}

pal_wifi_status_t pal_wifi_get_status(void) {
    return s_status;
}

int pal_wifi_get_ip(char *buf, size_t buf_len) {
    if (!buf || buf_len < 16) return -1;
    if (s_status != PAL_WIFI_CONNECTED) return -2;

    esp_netif_ip_info_t ip_info;
    if (esp_netif_get_ip_info(s_sta_netif, &ip_info) != ESP_OK) return -3;

    snprintf(buf, buf_len, IPSTR, IP2STR(&ip_info.ip));
    return 0;
}

void pal_wifi_set_callback(pal_wifi_callback_t cb, void *user_data) {
    s_callback = cb;
    s_callback_data = user_data;
}

int8_t pal_wifi_get_rssi(void) {
    wifi_ap_record_t ap;
    if (esp_wifi_sta_get_ap_info(&ap) == ESP_OK) {
        return ap.rssi;
    }
    return 0;
}